      <img src="https://www.kiantiong.com/images/kautian18-1.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian18-2.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian18-3.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian18-4.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian18-5.png" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian18-6.png" class="carousel-img" loading="lazy" />
    </div>
